/** A single PDF document of a research axis, generated by `scripts/build-axes.mjs`. */
export interface Poster {
  slug: string;
  /** Title shown under the PDF preview (cleaned file name, see build-axes.mjs). */
  title: string;
  /** Public path to the PDF, for example "/ejes/eje-1/<slug>.pdf". */
  pdf: string;
  /** Public path to the first-page thumbnail (WebP). */
  thumbnail: string;
  thumbnailWidth: number;
  thumbnailHeight: number;
  pages: number;
}

/** A research axis ("Eje") with its documents. */
export interface Category {
  /** "eje-1" … "eje-4"; also the section anchor id. */
  slug: string;
  number: number;
  name: string;
  posters: Poster[];
}

export interface CatalogData {
  categories: Category[];
}
